<script setup lang="ts">
import {ref} from 'vue'
import {roundingModes,safeSource,useStatutoryText} from '../statutoryPolicy'
import CdacRuleFields from './CdacRuleFields.vue'
import {useCdacText} from '../cdac'
import type {StatutoryConfig} from '../statutoryPolicy'
const props=defineProps<{config:StatutoryConfig;disabled:boolean}>(),{s}=useStatutoryText(),tab=ref('bands'),{d}=useCdacText(),emit=defineEmits<{loadCdac:[]}>(),table=ref('T1')
function addAge(){const c=props.config,last=c.ageBands.at(-1);if(!last)return;last.upperAge=Math.min(119,(c.ageBands.at(-2)?.upperAge??55)+5);const code='A'+crypto.randomUUID().slice(0,8).toUpperCase();c.ageBands.push({code,name:'',upperAge:null});for(const t of c.tables)t.rates.push({ageCode:code,employerRate:'0',employeeRate:'0'})}
function removeAge(code:string){const c=props.config;if(c.ageBands.length<2)return;c.ageBands=c.ageBands.filter(a=>a.code!==code);c.ageBands[c.ageBands.length-1].upperAge=null;for(const t of c.tables)t.rates=t.rates.filter(r=>r.ageCode!==code)}
</script>
<template><div class="statutory-editor"><div class="wf-subnav" role="tablist"><button v-for="key in (['bands','rates','sdl','cdac','sources'] as const)" :key="key" type="button" role="tab" :aria-selected="tab===key" @click="tab=key">{{s(key)}}</button></div><p class="wf-hint">{{s('ratio')}}</p><fieldset :disabled="disabled"><legend>{{s(tab as 'bands'|'rates'|'sdl'|'cdac'|'sources')}}</legend><section v-if="tab==='bands'"><label>{{s('ceiling')}}<input v-model="config.owCeiling" required inputmode="decimal"></label><div class="wf-table-wrap"><table><thead><tr><th>{{s('code')}}</th><th>{{s('name')}}</th><th>{{s('age')}}</th><th></th></tr></thead><tbody><tr v-for="(band,index) in config.ageBands" :key="band.code"><td>{{band.code}}</td><td><input v-model="band.name" required maxlength="80" :aria-label="s('name')+' '+band.code"></td><td><span v-if="index===config.ageBands.length-1">{{s('unlimited')}}</span><input v-else v-model.number="band.upperAge" required type="number" min="0" max="120" :aria-label="s('age')+' '+band.code"></td><td><button type="button" :disabled="config.ageBands.length<2" @click="removeAge(band.code)">{{s('remove')}}</button></td></tr></tbody></table></div><button type="button" :disabled="config.ageBands.length>=12" @click="addAge">{{s('addAge')}}</button><div class="wf-table-wrap"><table><thead><tr><th>{{s('code')}}</th><th>{{s('name')}}</th><th>{{s('wage')}}</th><th>{{s('method')}}</th><th>{{s('multiplier')}}</th></tr></thead><tbody><tr v-for="(band,index) in config.wageBands" :key="band.code"><td>{{band.code}}</td><td><input v-model="band.name" required maxlength="80" :aria-label="s('name')+' '+band.code"></td><td><span v-if="index===config.wageBands.length-1">{{s('unlimited')}}</span><input v-else v-model="band.upperWage" required inputmode="decimal" :aria-label="s('wage')+' '+band.code"></td><td>{{s(band.method)}}</td><td><input v-model="band.rampMultiplier" required inputmode="decimal" :aria-label="s('multiplier')+' '+band.code"></td></tr></tbody></table></div></section><section v-else-if="tab==='rates'"><label>{{s('rates')}}<select v-model="table"><option v-for="t in config.tables" :key="t.code" :value="t.code">{{t.code}} · {{t.name}}</option></select></label><template v-for="t in config.tables" :key="t.code"><div v-if="t.code===table"><label>{{s('name')}}<input v-model="t.name" required maxlength="100"></label><div class="wf-table-wrap"><table><thead><tr><th>{{s('age')}}</th><th>{{s('employer')}}</th><th>{{s('employee')}}</th></tr></thead><tbody><tr v-for="rate in t.rates" :key="rate.ageCode"><td>{{config.ageBands.find(a=>a.code===rate.ageCode)?.name}} · {{rate.ageCode}}</td><td><input v-model="rate.employerRate" required inputmode="decimal" :aria-label="t.code+' '+rate.ageCode+' '+s('employer')"></td><td><input v-model="rate.employeeRate" required inputmode="decimal" :aria-label="t.code+' '+rate.ageCode+' '+s('employee')"></td></tr></tbody></table></div></div></template></section><section v-else-if="tab==='sdl'" class="wf-filters"><label>{{s('rate')}}<input v-model="config.sdl.rate" required inputmode="decimal"></label><label>{{s('minimum')}}<input v-model="config.sdl.minimum" required inputmode="decimal"></label><label>{{s('maximum')}}<input v-model="config.sdl.maximum" required inputmode="decimal"></label><label v-for="field in (['totalCpf','employeeCpf','companySdl'] as const)" :key="field">{{s(field)}}<select v-model="config[`${field}Rounding`]"><option v-for="mode in roundingModes" :key="mode" :value="mode">{{s(mode)}}</option></select></label></section><section v-else-if="tab==='cdac'"><CdacRuleFields v-if="config.cdac" :rule="config.cdac"/><p v-else class="wf-hint">{{d('missing')}}</p><button type="button" @click="emit('loadCdac')">{{d('load')}}</button></section><section v-else class="wf-filters"><label v-for="field in (['cpfSource','sdlSource'] as const)" :key="field">{{s(field)}}<input v-model="config[field]" type="url" required maxlength="1000"><a v-if="safeSource(config[field])" :href="safeSource(config[field])" target="_blank" rel="noopener noreferrer">{{s('view')}}</a></label><label>{{s('notes')}}<textarea v-model="config.notes" maxlength="2000" rows="3"></textarea></label></section></fieldset><p class="wf-hint">{{s('timing')}}</p></div></template>
<style scoped>.statutory-editor fieldset{min-width:0;border:1px solid #e0e7ed;padding:12px}.statutory-editor .wf-subnav{gap:6px;margin-top:12px}.statutory-editor [aria-selected="true"]{font-weight:650;background:#e7eff6}.statutory-editor table input{width:100%;min-width:80px}.statutory-editor td{min-width:100px}.statutory-editor section>.wf-table-wrap{margin:10px 0}.statutory-editor label{display:flex;flex-direction:column;gap:4px;font-size:12px}.statutory-editor .wf-filters{align-items:start}</style>
